  SELECT id INTO fw_id FROM frameworks WHERE code = $cw$nist_800_171$cw$ ORDER BY created_at LIMIT 1;
  IF fw_id IS NULL THEN
    INSERT INTO frameworks (code, name, version, description, category, tier_required, is_active, coverage_status)
    VALUES ($cw$nist_800_171$cw$, $cw$NIST SP 800-171 Rev 3$cw$, $cw$Rev 3$cw$, $cw$Protecting Controlled Unclassified Information (CUI) in nonfederal systems and organizations: all 97 security requirements across 17 families.$cw$, $cw$CUI Protection$cw$, $cw$pro$cw$, true, 'comprehensive')
    RETURNING id INTO fw_id;
  ELSE
    UPDATE frameworks
       SET name = $cw$NIST SP 800-171 Rev 3$cw$, version = $cw$Rev 3$cw$, description = $cw$Protecting Controlled Unclassified Information (CUI) in nonfederal systems and organizations: all 97 security requirements across 17 families.$cw$,
           category = $cw$CUI Protection$cw$, coverage_status = 'comprehensive'
     WHERE id = fw_id;
