     AND child.parent_control_id IS DISTINCT FROM parent.id;

  -- fedramp_moderate: 323 controls
  SELECT id INTO fw_id FROM frameworks WHERE code = $cw$fedramp_moderate$cw$ ORDER BY created_at LIMIT 1;
  IF fw_id IS NULL THEN
    INSERT INTO frameworks (code, name, version, description, category, tier_required, is_active, coverage_status)
    VALUES ($cw$fedramp_moderate$cw$, $cw$FedRAMP Moderate Baseline$cw$, $cw$5.2.0$cw$, $cw$FedRAMP Moderate baseline for cloud services processing Controlled Unclassified Information for US federal agencies. FedRAMP Rev 5 Moderate baseline: 323 NIST SP 800-53 Rev 5 controls and enhancements with FedRAMP-defined parameters and additional requirements; continuous monitoring (ConMon) and 3PAO assessment apply on top. Source: FedRAMP's Rev 5 baseline workbook, which FedRAMP marked legacy on 2026-06-23 in favor of the FedRAMP Consolidated Rules for 2026.$cw$, $cw$Federal Cloud Security$cw$, $cw$community$cw$, true, 'comprehensive')
    RETURNING id INTO fw_id;
