    JOIN framework_controls parent ON parent.framework_id = fw_id AND parent.control_id = v.parent_code
   WHERE child.framework_id = fw_id AND child.control_id = v.control_id
     AND child.parent_control_id IS DISTINCT FROM parent.id;

  -- fedramp_high: 410 controls
  SELECT id INTO fw_id FROM frameworks WHERE code = $cw$fedramp_high$cw$ ORDER BY created_at LIMIT 1;
  IF fw_id IS NULL THEN
    INSERT INTO frameworks (code, name, version, description, category, tier_required, is_active, coverage_status)
    VALUES ($cw$fedramp_high$cw$, $cw$FedRAMP High Baseline$cw$, $cw$5.2.0$cw$, $cw$FedRAMP High baseline, required for systems processing law enforcement, emergency services, financial and health data. FedRAMP Rev 5 High baseline: 410 NIST SP 800-53 Rev 5 controls and enhancements with FedRAMP-defined parameters and additional requirements. Source: FedRAMP's Rev 5 baseline workbook, which FedRAMP marked legacy on 2026-06-23 in favor of the FedRAMP Consolidated Rules for 2026.$cw$, $cw$Federal Cloud Security$cw$, $cw$community$cw$, true, 'comprehensive')
    RETURNING id INTO fw_id;
  ELSE
    UPDATE frameworks
       SET name = $cw$FedRAMP High Baseline$cw$, version = $cw$5.2.0$cw$, description = $cw$FedRAMP High baseline, required for systems processing law enforcement, emergency services, financial and health data. FedRAMP Rev 5 High baseline: 410 NIST SP 800-53 Rev 5 controls and enhancements with FedRAMP-defined parameters and additional requirements. Source: FedRAMP's Rev 5 baseline workbook, which FedRAMP marked legacy on 2026-06-23 in favor of the FedRAMP Consolidated Rules for 2026.$cw$,
           category = $cw$Federal Cloud Security$cw$, coverage_status = 'comprehensive'
     WHERE id = fw_id;
  END IF;

  INSERT INTO framework_controls (framework_id, control_id, title, description, control_type, priority, is_enhancement)
  SELECT fw_id, v.control_id, v.title, v.description, v.control_type, v.priority, v.is_enhancement
    FROM (VALUES
      ($cw$FRH-AC-1$cw$, $cw$Policy and Procedures$cw$, $cw$a. Develop, document, and disseminate to [organization-defined personnel or roles]: 1. [organization-level | mission/business process-level | system-level] access control policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and 2. Procedures to facilitate the implementation of the access control policy and the associated access controls; b. Designate an [official] to manage the development, documentation, and dissemination of the access control policy and procedures; and c. Review and update the current access control: 1. Policy [frequency] and following [events] ; and 2. Procedures [frequency] and following [events].

FedRAMP-defined parameters:
AC-1 (c) (1) [at least annually]
AC-1 (c) (2) [at least annually] [significant changes]$cw$, $cw$technical$cw$, $cw$2$cw$, false),
      ($cw$FRH-AC-2$cw$, $cw$Account Management$cw$, $cw$a. Define and document the types of accounts allowed and specifically prohibited for use within the system; b. Assign account managers; c. Require [prerequisites and criteria] for group and role membership; d. Specify: 1. Authorized users of the system; 2. Group and role membership; and 3. Access authorizations (i.e., privileges) and [attributes (as required)] for each account; e. Require approvals by [personnel or roles] for requests to create accounts; f. Create, enable, modify, disable, and remove accounts in accordance with [policy, procedures, prerequisites, and criteria]; g. Monitor the use of accounts; h. Notify account managers and [personnel or roles] within: 1. [time period] when accounts are no longer required; 2. [time period] when users are terminated or transferred; and 3. [time period] when system usage or need-to-know changes for an individual; i. Authorize access to the system based on: 1. A valid access authorization; 2. Intended system usage; and 3. [attributes (as required)]; j. Review accounts for compliance with account management requirements [frequency]; k. Establish and implement a process for changing shared or group account authenticators (if deployed) when individuals are removed from the group; and l. Align account management processes with personnel termination and transfer processes.

FedRAMP-defined parameters:
AC-2 (h) (1) [twenty-four (24) hours]
AC-2 (h) (2) [eight (8) hours]
AC-2 (h) (3) [eight (8) hours]
AC-2 (j) [monthly for privileged accessed, every six (6) months for non-privileged access]$cw$, $cw$technical$cw$, $cw$2$cw$, false),
      ($cw$FRH-AC-2(1)$cw$, $cw$Automated System Account Management$cw$, $cw$Support the management of system accounts using [automated mechanisms].$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-2(2)$cw$, $cw$Automated Temporary and Emergency Account Management$cw$, $cw$Automatically [remove | disable] temporary and emergency accounts after [time period].

FedRAMP-defined parameters:
AC-2 (2) [Selection: disables]
[Assignment: no more than 24 hours from last use]$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-2(3)$cw$, $cw$Disable Accounts$cw$, $cw$Disable accounts within [time period] when the accounts:

FedRAMP-defined parameters:
AC-2 (3) [24 hours for user accounts]
AC-2 (3) (d) [thirty-five (35) days] (See additional requirements and guidance.)

Additional FedRAMP requirements and guidance:
AC-2 (3) Requirement: The service provider defines the time period for non-user accounts (e.g., accounts associated with devices). Where user management is a function of the service, reports of activity of consumer users shall be made available.
AC-2 (3) (d) Requirement: The service provider defines the time period of inactivity for device identifiers.
Guidance: For DoD clouds, see DoD cloud website for specific DoD requirements that go above and beyond FedRAMP https://public.cyber.mil/dccs/.$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-2(4)$cw$, $cw$Automated Audit Actions$cw$, $cw$Automatically audit account creation, modification, enabling, disabling, and removal actions.$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-2(5)$cw$, $cw$Inactivity Logout$cw$, $cw$Require that users log out when [time period of expected inactivity or description of when to log out].

FedRAMP-defined parameters:
AC-2 (5) [inactivity is anticipated to exceed Fifteen (15) minutes]

Additional FedRAMP requirements and guidance:
AC-2 (5) Guidance: Should use a shorter timeframe than AC-12.$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-2(7)$cw$, $cw$Privileged User Accounts$cw$, $cw$(a) Establish and administer privileged user accounts in accordance with [a role-based access scheme | an attribute-based access scheme]; (b) Monitor privileged role or attribute assignments; (c) Monitor changes to roles or attributes; and (d) Revoke access when privileged role or attribute assignments are no longer appropriate.$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-2(9)$cw$, $cw$Restrictions on Use of Shared and Group Accounts$cw$, $cw$Only permit the use of shared and group accounts that meet [conditions].

FedRAMP-defined parameters:
AC-2 (9) [organization-defined need with justification statement that explains why such accounts are necessary]

Additional FedRAMP requirements and guidance:
AC-2 (9) Requirement: Required if shared/group accounts are deployed$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-2(11)$cw$, $cw$Usage Conditions$cw$, $cw$Enforce [circumstances and/or usage conditions] for [system accounts].$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-2(12)$cw$, $cw$Account Monitoring for Atypical Usage$cw$, $cw$(a) Monitor system accounts for [atypical usage] ; and (b) Report atypical usage of system accounts to [personnel or roles].

FedRAMP-defined parameters:
AC-2 (12) (b)[at a minimum, the ISSO and/or similar role within the organization]

Additional FedRAMP requirements and guidance:
AC-2 (12) (a) Requirement: Required for privileged accounts.
AC-2 (12) (b) Requirement: Required for privileged accounts.$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-2(13)$cw$, $cw$Disable Accounts for High-risk Individuals$cw$, $cw$Disable accounts of individuals within [time period] of discovery of [significant risks].

FedRAMP-defined parameters:
AC-2 (13)-1 [one (1) hour]$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-3$cw$, $cw$Access Enforcement$cw$, $cw$Enforce approved authorizations for logical access to information and system resources in accordance with applicable access control policies.$cw$, $cw$technical$cw$, $cw$2$cw$, false),
      ($cw$FRH-AC-4$cw$, $cw$Information Flow Enforcement$cw$, $cw$Enforce approved authorizations for controlling the flow of information within the system and between connected systems based on [information flow control policies].$cw$, $cw$technical$cw$, $cw$2$cw$, false),
      ($cw$FRH-AC-4(4)$cw$, $cw$Flow Control of Encrypted Information$cw$, $cw$Prevent encrypted information from bypassing [information flow control mechanisms] by [decrypting the information | blocking the flow of the encrypted information | terminating communications sessions attempting to pass encrypted information | [organization-defined procedure or method]].

FedRAMP-defined parameters:
AC-4 (4)-1 [intrusion detection mechanisms]

Additional FedRAMP requirements and guidance:
AC-4 (4) Requirement: The service provider must support Agency requirements to comply with M-21-31 (https://www.whitehouse.gov/wp-content/uploads/2021/08/M-21-31-Improving-the-Federal-Governments-Investigative-and-Remediation-Capabilities-Related-to-Cybersecurity-Incidents.pdf) and M-22-09 (https://www.whitehouse.gov/wp-content/uploads/2022/01/M-22-09.pdf). Implementation of this control by service providers should specifically support the methods used by agency customers to provide visibility into their encrypted communications between agency networks and the cloud service boundary so that the confidentiality, integrity, or availability of federal customer within the boundary of the cloud service is not negatively impacted. This additional requirement should be automatically updated if M-21-31 or M-22-09 is rescinded, updated, or replaced.$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-4(21)$cw$, $cw$Physical or Logical Separation of Information Flows$cw$, $cw$Separate information flows logically or physically using [organization-defined mechanisms and/or techniques] to accomplish [required separations].$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-5$cw$, $cw$Separation of Duties$cw$, $cw$a. Identify and document [duties of individuals] ; and b. Define system access authorizations to support separation of duties.

Additional FedRAMP requirements and guidance:
AC-5 Guidance: CSPs have the option to provide a separation of duties matrix as an attachment to the SSP.$cw$, $cw$technical$cw$, $cw$2$cw$, false),
      ($cw$FRH-AC-6$cw$, $cw$Least Privilege$cw$, $cw$Employ the principle of least privilege, allowing only authorized accesses for users (or processes acting on behalf of users) that are necessary to accomplish assigned organizational tasks.$cw$, $cw$technical$cw$, $cw$2$cw$, false),
      ($cw$FRH-AC-6(1)$cw$, $cw$Authorize Access to Security Functions$cw$, $cw$Authorize access for [individuals and roles] to:

FedRAMP-defined parameters:
AC-6 (1) (a) [all functions not publicly accessible]
AC-6 (1) (b) [all security-relevant information not publicly available]$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-6(2)$cw$, $cw$Non-privileged Access for Nonsecurity Functions$cw$, $cw$Require that users of system accounts (or roles) with access to [security functions or security-relevant information] use non-privileged accounts or roles, when accessing nonsecurity functions.

FedRAMP-defined parameters:
AC-6 (2) [all security functions]

Additional FedRAMP requirements and guidance:
AC-6 (2) Guidance:  Examples of security functions include but are not limited to: establishing system accounts, configuring access authorizations (i.e., permissions, privileges), setting events to be audited, and setting intrusion detection parameters, system programming, system and security administration, other privileged functions.$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-6(3)$cw$, $cw$Network Access to Privileged Commands$cw$, $cw$Authorize network access to [privileged commands] only for [compelling operational needs] and document the rationale for such access in the security plan for the system.

FedRAMP-defined parameters:
AC-6 (3)-1 [all privileged commands]$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-6(5)$cw$, $cw$Privileged Accounts$cw$, $cw$Restrict privileged accounts on the system to [personnel or roles].$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-6(7)$cw$, $cw$Review of User Privileges$cw$, $cw$(a) Review [frequency] the privileges assigned to [roles and classes] to validate the need for such privileges; and (b) Reassign or remove privileges, if necessary, to correctly reflect organizational mission and business needs.

FedRAMP-defined parameters:
AC-6 (7) (a)-1  [at a minimum, annually]
AC-6 (7) (a)-2  [all users with privileges]$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-6(8)$cw$, $cw$Privilege Levels for Code Execution$cw$, $cw$Prevent the following software from executing at higher privilege levels than users executing the software: [software].

FedRAMP-defined parameters:
AC-6 (8) [any software except software explicitly documented]$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-6(9)$cw$, $cw$Log Use of Privileged Functions$cw$, $cw$Log the execution of privileged functions.$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-6(10)$cw$, $cw$Prohibit Non-privileged Users from Executing Privileged Functions$cw$, $cw$Prevent non-privileged users from executing privileged functions.$cw$, $cw$technical$cw$, $cw$2$cw$, true),
      ($cw$FRH-AC-7$cw$, $cw$Unsuccessful Logon Attempts$cw$, $cw$a. Enforce a limit of [number] consecutive invalid logon attempts by a user during a [time period] ; and b. Automatically [lock the account or node for [time period] | lock the account or node until released by an administrator | delay next logon prompt per [delay algorithm] | notify system administrator | take other [action]] when the maximum number of unsuccessful attempts is exceeded.

Additional FedRAMP requirements and guidance:
AC-7 Requirement: In alignment with NIST SP 800-63B$cw$, $cw$technical$cw$, $cw$2$cw$, false),
      ($cw$FRH-AC-8$cw$, $cw$System Use Notification$cw$, $cw$a. Display [system use notification] to users before granting access to the system that provides privacy and security notices consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines and state that: 1. Users are accessing a U.S. Government system; 2. System usage may be monitored, recorded, and subject to audit; 3. Unauthorized use of the system is prohibited and subject to criminal and civil penalties; and 4. Use of the system indicates consent to monitoring and recording; b. Retain the notification message or banner on the screen until users acknowledge the usage conditions and take explicit actions to log on to or further access the system; and c. For publicly accessible systems: 1. Display system use information [conditions] , before granting further access to the publicly accessible system; 2. Display references, if any, to monitoring, recording, or auditing that are consistent with privacy accommodations for such systems that generally prohibit those activities; and 3. Include a description of the authorized uses of the system.

FedRAMP-defined parameters:
AC-8 (a) [see additional Requirements and Guidance]
AC-8 (c) (1) [see additional Requirements and Guidance]

Additional FedRAMP requirements and guidance:
AC-8 Requirement: The service provider shall determine elements of the cloud environment that require the System Use Notification control.

Requirement: The service provider shall determine how System Use Notification is going to be verified and provide appropriate periodicity of the check.

Requirement: If not performed as part of a Configuration Baseline check, then there must be documented agreement on how to provide results of verification and the necessary periodicity of the verification by the service provider.

Guidance: If performed as part of a Configuration Baseline check, then the % of items requiring setting that are checked and that pass (or fail) check can be provided.$cw$, $cw$technical$cw$, $cw$2$cw$, false),
      ($cw$FRH-AC-10$cw$, $cw$Concurrent Session Control$cw$, $cw$Limit the number of concurrent sessions for each [account and/or account types] to [number].

FedRAMP-defined parameters:
AC-10-2 [three (3) sessions for privileged access and two (2) sessions for non-privileged access]$cw$, $cw$technical$cw$, $cw$2$cw$, false),
      ($cw$FRH-AC-11$cw$, $cw$Device Lock$cw$, $cw$a. Prevent further access to the system by [initiating a device lock after [time period] of inactivity | requiring the user to initiate a device lock before leaving the system unattended] ; and b. Retain the device lock until the user reestablishes access using established identification and authentication procedures.

FedRAMP-defined parameters:
AC-11 (a) [fifteen (15) minutes]; requiring the user to initiate a device lock before leaving the system unattended$cw$, $cw$technical$cw$, $cw$2$cw$, false),
      ($cw$FRH-AC-11(1)$cw$, $cw$Pattern-hiding Displays$cw$, $cw$Conceal, via the device lock, information previously visible on the display with a publicly viewable image.$cw$, $cw$technical$cw$, $cw$2$cw$, true),
